CREATE UNIQUE INDEX IF NOT EXISTS "client_funding_opportunity_grant_uniq"
    ON "client_funding_opportunity" ("tenant_id", "client_id", "grant_opportunity_id")
    WHERE "grant_opportunity_id" IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "client_funding_opportunity_sam_uniq"
    ON "client_funding_opportunity" ("tenant_id", "client_id", "sam_opportunity_id")
    WHERE "sam_opportunity_id" IS NOT NULL;

CREATE INDEX IF NOT EXISTS "client_funding_opportunity_decision_idx"
    ON "client_funding_opportunity" ("tenant_id", "human_decision", "next_action_due_at")
    WHERE "human_decision" IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "tango_resource_snapshot_one_active_uniq"
    ON "tango_resource_snapshot" ("resource_type", "external_id")
    WHERE "active" = true;

CREATE UNIQUE INDEX IF NOT EXISTS "tango_budget_vendor_flow_grain_uniq"
  ON "tango_budget_vendor_flow" (
    "budget_account_id",
    "recipient_uei",
    COALESCE("funding_organization_id", '')
  );

CREATE UNIQUE INDEX "client_funding_opportunity_generic_uniq"
  ON "client_funding_opportunity" ("tenant_id", "client_id", "source", "source_record_type", "source_record_key")
  WHERE "source_record_key" IS NOT NULL AND "source_record_type" IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "engagement_tasks_tenant_source_uniq"
    ON "engagement_tasks" ("tenant_id", "source_type", "source_id")
    WHERE "source_type" IS NOT NULL AND "source_id" IS NOT NULL;
